// Supabase Edge Function: speak-reply
// Receives { text, lang } and returns { pcm, sampleRate } — natural speech
// audio generated by Gemini TTS, so Bolo sounds human instead of robotic.

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Client-Info, Apikey",
};

const TTS_MODEL = "gemini-2.5-flash-preview-tts";
const VOICE = "Kore"; // warm, consistent voice across languages

function json(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 200, headers: corsHeaders });
  }

  try {
    if (req.method !== "POST") {
      return json(405, { error: "Method not allowed" });
    }

    const apiKey = Deno.env.get("GEMINI_API_KEY");
    if (!apiKey) {
      return json(503, { error: "Voice is not configured" });
    }

    let body: { text?: unknown };
    try {
      body = await req.json();
    } catch {
      return json(400, { error: "Invalid request body" });
    }

    const text = typeof body.text === "string" ? body.text.trim().slice(0, 400) : "";
    if (!text) {
      return json(400, { error: "Nothing to speak" });
    }

    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 12_000);
    const response = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/${TTS_MODEL}:generateContent?key=${apiKey}`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        signal: controller.signal,
        body: JSON.stringify({
          contents: [{ parts: [{ text }] }],
          generationConfig: {
            responseModalities: ["AUDIO"],
            speechConfig: {
              voiceConfig: { prebuiltVoiceConfig: { voiceName: VOICE } },
            },
          },
        }),
      }
    );
    clearTimeout(timer);

    if (!response.ok) {
      console.log(`speak-reply: gemini tts failed: HTTP ${response.status}`);
      return json(502, { error: "Could not generate speech" });
    }

    const payload = await response.json().catch(() => null);
    const part = payload?.candidates?.[0]?.content?.parts?.find(
      (p: { inlineData?: unknown }) => p.inlineData
    );
    const inline = part?.inlineData as { data?: unknown; mimeType?: unknown } | undefined;
    if (!inline || typeof inline.data !== "string") {
      return json(502, { error: "Could not generate speech" });
    }

    const rateMatch =
      typeof inline.mimeType === "string" ? inline.mimeType.match(/rate=(\d+)/) : null;
    const sampleRate = rateMatch ? parseInt(rateMatch[1], 10) : 24000;

    return json(200, { pcm: inline.data, sampleRate });
  } catch (_err) {
    return json(500, { error: "Could not generate speech" });
  }
});
